def _num(v, default):
    try:
        return float(v)
    except (TypeError, ValueError):
        return default


def _xy(lat, lng):
    return (lng - _LON0) * _K * _C, (_LAT0 - lat) * _K


def _curve(a, b):
    """Gently bent path from a to b (bends to the right of the direction of travel)."""
    (x1, y1), (x2, y2) = a, b
    dx, dy = x2 - x1, y2 - y1
    dist = math.hypot(dx, dy) or 1
    bend = min(0.22 * dist, 60)
    cx, cy = (x1 + x2) / 2 - dy / dist * bend, (y1 + y2) / 2 + dx / dist * bend
    return f'M{x1:.1f} {y1:.1f} Q{cx:.1f} {cy:.1f} {x2:.1f} {y2:.1f}'


def thai_map(d, uid='thm'):
    """HTML for the map plus the numbered list of zones. Empty when no zones are set."""
    pts = [p for p in items(d, 'map_points') if s(p, 'lat') != '' and s(p, 'lng') != '']
    if not pts:
        return ''
    o = _xy(_num(d.get('map_origin_lat'), 13.52), _num(d.get('map_origin_lng'), 100.66))
    routes, cars, dots = [], [], []
    for i, p in enumerate(pts):
        xy = _xy(_num(p.get('lat'), 13.7), _num(p.get('lng'), 100.5))
        rid = f'{uid}-r{i}'
        dur = 2.2 + min(math.hypot(xy[0] - o[0], xy[1] - o[1]) / 90, 3.2)
        routes.append(f'<path id="{rid}" class="thmap-route" d="{_curve(o, xy)}" pathLength="1" style="--i:{i}"/>')
        cars.append(f'<circle class="thmap-car" r="3"><animateMotion dur="{dur:.1f}s" begin="{0.6 + i * 0.45:.2f}s" repeatCount="indefinite">'
                    f'<mpath href="#{rid}"/></animateMotion></circle>')
        dots.append(f'<g class="thmap-pin" data-pin="{i}" style="--i:{i}"><circle cx="{xy[0]:.1f}" cy="{xy[1]:.1f}" r="7.5"/>'
                    f'<text x="{xy[0]:.1f}" y="{xy[1] + 3.3:.1f}" text-anchor="middle">{i + 1}</text></g>')
    ox, oy = o
    origin = (f'<g class="thmap-hq"><circle class="thmap-ring" cx="{ox:.1f}" cy="{oy:.1f}" r="7"/>'
              f'<circle class="thmap-ring r2" cx="{ox:.1f}" cy="{oy:.1f}" r="7"/>'
              f'<circle class="thmap-origin" cx="{ox:.1f}" cy="{oy:.1f}" r="7"/>'
              f'<text x="{ox + 12:.1f}" y="{oy + 4:.1f}">SuperX AI</text></g>')
    legend = [f'<li class="is-hq"><span class="thmap-num">HQ</span><span><b>{TC(tri(d, "map_origin"))}</b>{B("small", tri(d, "map_origin_text"))}</span></li>']
    for i, p in enumerate(pts):
        legend.append(f'<li data-pin="{i}"><span class="thmap-num">{i + 1}</span><span><b>{TC(tri(p, "name"))}</b>{B("small", tri(p, "text"))}</span></li>')
    title = B('h3', tri(d, 'map_title'), cls='h3 thmap-title')
    return f'''<div class="thmap" data-thmap>
    <div class="thmap-art"><svg viewBox="0 0 {W} {H}" role="img" aria-label="{esc(tri(d, "map_title")[2] or "Service map of Thailand")}">
      <path class="thmap-land" d="{LAND}"/>
      <g class="thmap-routes">{"".join(routes)}</g>
      <g class="thmap-cars">{"".join(cars)}</g>
      {"".join(dots)}{origin}
    </svg></div>
    <div class="thmap-side">{title}
      <ol class="thmap-legend">{"".join(legend)}</ol>
    </div>
  </div>'''
